-- ASMI Medical - BASE COMPLETA extraida del HTML original
-- Personal: 7776 | Pacientes: 980
CREATE DATABASE IF NOT EXISTS asmi_medical CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE asmi_medical;

DROP TABLE IF EXISTS citas;
DROP TABLE IF EXISTS recetas;
DROP TABLE IF EXISTS pacientes;
DROP TABLE IF EXISTS personal;
DROP TABLE IF EXISTS medicos;
DROP TABLE IF EXISTS hospitales;
DROP TABLE IF EXISTS especialidades;

CREATE TABLE hospitales (
  id INT AUTO_INCREMENT PRIMARY KEY,
  clave VARCHAR(30) UNIQUE,
  nombre VARCHAR(150),
  estado VARCHAR(80),
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE especialidades (
  id INT AUTO_INCREMENT PRIMARY KEY,
  nombre VARCHAR(80) UNIQUE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE personal (
  id INT AUTO_INCREMENT PRIMARY KEY,
  hospital_id INT,
  clave_hospital VARCHAR(30),
  hospital VARCHAR(150),
  estado VARCHAR(80),
  tipo VARCHAR(30),
  area VARCHAR(80),
  rol VARCHAR(80),
  especialidad VARCHAR(80),
  nombre VARCHAR(150),
  usuario VARCHAR(80) UNIQUE,
  password VARCHAR(255),
  correo VARCHAR(150),
  consultorio VARCHAR(150),
  cedula VARCHAR(50),
  KEY idx_hospital (clave_hospital),
  KEY idx_usuario (usuario),
  KEY idx_nombre (nombre)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE pacientes (
  id INT AUTO_INCREMENT PRIMARY KEY,
  folio_ins VARCHAR(40) UNIQUE,
  nss VARCHAR(20),
  nombre VARCHAR(180),
  hospital_clave VARCHAR(30),
  hospital VARCHAR(150),
  estado VARCHAR(80),
  cama VARCHAR(30),
  consultorio VARCHAR(100),
  especialidad VARCHAR(80),
  fecha_ingreso VARCHAR(30),
  medico_origen VARCHAR(150),
  medico_actual VARCHAR(150),
  tipo VARCHAR(30),
  KEY idx_nss (nss),
  KEY idx_folio (folio_ins),
  KEY idx_hospital (hospital_clave)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE citas (
  id INT AUTO_INCREMENT PRIMARY KEY,
  paciente_nss VARCHAR(20) NOT NULL,
  paciente_folio VARCHAR(40),
  medico_nombre VARCHAR(150),
  area VARCHAR(80),
  fecha DATE,
  hora TIME,
  hospital_clave VARCHAR(30),
  consultorio VARCHAR(100),
  estado ENUM('Agendada','Cancelada','Atendida') DEFAULT 'Agendada',
  UNIQUE KEY unique_cita (paciente_nss, fecha, hora),
  KEY idx_paciente_nss (paciente_nss)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE recetas (
  id INT AUTO_INCREMENT PRIMARY KEY,
  folio VARCHAR(40) UNIQUE,
  paciente_folio VARCHAR(40),
  medicamento TEXT,
  indicaciones TEXT,
  fecha DATE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

